const listMaintenanceWindows = `-- name: ListMaintenanceWindows :many
SELECT w.id, w.workspace_id, w.title, w.description, w.starts_at, w.ends_at, w.canceled_at, w.created_by, w.created_at, w.updated_at FROM maintenance_windows w
WHERE w.workspace_id = $1
  AND ($2::text IS NULL
       OR ($2::text = 'upcoming' AND w.canceled_at IS NULL AND w.starts_at > $3::timestamptz)
       OR ($2::text = 'active' AND w.canceled_at IS NULL AND w.starts_at <= $3::timestamptz
           AND w.ends_at > $3::timestamptz)
       OR ($2::text = 'past' AND (w.canceled_at IS NOT NULL OR w.ends_at <= $3::timestamptz)))
  AND ($4::uuid IS NULL
       OR EXISTS (SELECT 1 FROM maintenance_window_pages wp WHERE wp.window_id = w.id AND wp.page_id = $4::uuid))
  AND ($5::timestamptz IS NULL
       OR (w.starts_at, w.id) < ($5::timestamptz, $6::uuid))
ORDER BY w.starts_at DESC, w.id DESC
LIMIT $7
`

type ListMaintenanceWindowsParams struct {
	WorkspaceID    uuid.UUID  `json:"workspaceId"`
	Phase          *string    `json:"phase"`
	AsOf           time.Time  `json:"asOf"`
	PageID         *uuid.UUID `json:"pageId"`
	CursorStartsAt *time.Time `json:"cursorStartsAt"`
	CursorID       *uuid.UUID `json:"cursorId"`
	RowLimit       int32      `json:"rowLimit"`
}

// Latest start first. phase: upcoming (not started, not canceled), active (running, not canceled),
// past (ended or canceled); page_id = posted to that page.
func (q *Queries) ListMaintenanceWindows(ctx context.Context, arg ListMaintenanceWindowsParams) ([]MaintenanceWindow, error) {
	rows, err := q.db.Query(ctx, listMaintenanceWindows,
		arg.WorkspaceID,
		arg.Phase,
		arg.AsOf,
		arg.PageID,
		arg.CursorStartsAt,
		arg.CursorID,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []MaintenanceWindow{}
	for rows.Next() {
		var i MaintenanceWindow
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.Title,
			&i.Description,
			&i.StartsAt,
			&i.EndsAt,
			&i.CanceledAt,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listOriginLockStatusPages = `-- name: ListOriginLockStatusPages :many
SELECT sp.id AS page_id, COALESCE(sp.hostname, '')::text AS hostname, sp.cf_zone_id AS zone_id, sp.workspace_id, COALESCE(aop.state, '')::text AS aop_state
FROM status_pages sp
LEFT JOIN cloudflare_zone_aop aop ON aop.workspace_id = sp.workspace_id AND aop.zone_id = sp.cf_zone_id
WHERE sp.hostname = ANY($1::text[])
  AND sp.published AND sp.cf_origin_lock AND sp.cf_proxied AND sp.cf_zone_id <> ''
  AND EXISTS (
      SELECT 1 FROM cloudflare_records r
      WHERE r.zone_id = sp.cf_zone_id AND r.hostname = sp.hostname AND r.proxied AND r.type IN ('A','AAAA'))
`

