const listStatusIncidents = `-- name: ListStatusIncidents :many
SELECT i.id, i.workspace_id, i.title, i.impact, i.status, i.created_by, i.created_at, i.updated_at, i.resolved_at FROM status_incidents i
WHERE i.workspace_id = $1
  AND ($2::text IS NULL OR i.status = $2::text)
  AND ($3::boolean IS NULL OR (i.resolved_at IS NULL) = $3::boolean)
  AND ($4::uuid IS NULL
       OR EXISTS (SELECT 1 FROM status_incident_pages ip WHERE ip.incident_id = i.id AND ip.page_id = $4::uuid))
  AND ($5::timestamptz IS NULL
       OR (i.created_at, i.id) < ($5::timestamptz, $6::uuid))
ORDER BY i.created_at DESC, i.id DESC
LIMIT $7
`

type ListStatusIncidentsParams struct {
	WorkspaceID     uuid.UUID  `json:"workspaceId"`
	Status          *string    `json:"status"`
	Active          *bool      `json:"active"`
	PageID          *uuid.UUID `json:"pageId"`
	CursorCreatedAt *time.Time `json:"cursorCreatedAt"`
	CursorID        *uuid.UUID `json:"cursorId"`
	RowLimit        int32      `json:"rowLimit"`
}

// Newest first. status filters one status, active = not resolved yet, page_id = posted to that page.
func (q *Queries) ListStatusIncidents(ctx context.Context, arg ListStatusIncidentsParams) ([]StatusIncident, error) {
	rows, err := q.db.Query(ctx, listStatusIncidents,
		arg.WorkspaceID,
		arg.Status,
		arg.Active,
		arg.PageID,
		arg.CursorCreatedAt,
		arg.CursorID,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []StatusIncident{}
	for rows.Next() {
		var i StatusIncident
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.Title,
			&i.Impact,
			&i.Status,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ResolvedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listStatusOriginLockServerIDs = `-- name: ListStatusOriginLockServerIDs :many
SELECT srv.id
FROM servers srv
WHERE srv.is_control_plane
  AND EXISTS (
      SELECT 1 FROM status_pages sp
      WHERE sp.published AND sp.cf_origin_lock AND sp.cf_proxied AND sp.cf_zone_id <> ''
        AND ($1::text = '' OR sp.cf_zone_id = $1::text)
        AND EXISTS (
            SELECT 1 FROM cloudflare_records r
            WHERE r.zone_id = sp.cf_zone_id AND r.hostname = sp.hostname AND r.proxied AND r.type IN ('A','AAAA')))
ORDER BY srv.id
`

// The control-plane server when a published page may be origin-locked (opted in,
// proxied record of ours). zone_id restricts to one zone; empty means every zone.
func (q *Queries) ListStatusOriginLockServerIDs(ctx context.Context, zoneID string) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, listStatusOriginLockServerIDs, zoneID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listStatusPageComponents = `-- name: ListStatusPageComponents :many

SELECT c.page_id, c.service_id, c.display_name, c.group_name, c.url, c.position,
       s.name AS service_name, e.name AS environment_name, p.id AS project_id, p.name AS project_name
FROM status_page_components c
JOIN status_pages sp ON sp.id = c.page_id
JOIN services s ON s.id = c.service_id AND s.deleted_at IS NULL
JOIN environments e ON e.id = s.environment_id
JOIN projects p ON p.id = e.project_id
WHERE sp.workspace_id = $1
  AND ($2::uuid IS NULL OR c.page_id = $2::uuid)
ORDER BY c.page_id, c.position
`

